function Hd = FIR_Gr2
%FIR_GR2 Returns a discrete-time filter object.

% MATLAB Code
% Generated by MATLAB(R) 9.7 and Signal Processing Toolbox 8.3.
% Generated on: 18-Oct-2024 09:33:05

% FIR Window Lowpass filter designed using the FIR1 function.

% All frequency values are in Hz.
Fs = 8000;  % Sampling Frequency

N    = 127;      % Order
Fc   = 1000;     % Cutoff Frequency
flag = 'scale';  % Sampling Flag
Beta = 10;       % Window Parameter

% Create the window vector for the design algorithm.
win = kaiser(N+1, Beta);

% Calculate the coefficients using the FIR1 function.
b  = fir1(N, Fc/(Fs/2), 'low', win, flag);

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
h = b;
reponse = input('Génération des coefficients pour l''assembleur tapez 0 pour C tapez 1:  ');
if reponse == 1 
    fid = fopen('FIR_COEF_VF.h','w');
    fprintf(fid,'#define    N     %d      // Nombre de coefficients du filtre \n\n', N+1);
    fprintf(fid, '// Frequence d''echantillonnage Fs = %d  \n\n', Fs);
    fprintf(fid,'float h[%d',N+1);
    fprintf(fid,']= {');
    for i=1:N
        fprintf(fid,'%f,',h(i));
        if mod(i,16) == 0    fprintf(fid, '\n');
        end
    end
    fprintf(fid,'%d };\n', h(N+1));
else
    fid = fopen('FIR_COEF_VF.asm','w');
    fprintf(fid, 'N    EQU    %d\n\n',N+1);
    for i=0:N    fprintf(fid,'h%d     .word   %d\n',i, h(i+1));
    end;
end
fclose(fid);
% [EOF]
